    'table purges',
    'table routine_exercises',
    'table routines',
    'table saved_foods',
    'table sessions',
    'table sets',
    'table settings',
    'table weigh_ins',
    'trigger cardio_sessions.cardio_sessions_guard O d758b59d6bcb0f5bce9cfc4638f368a2',
    'trigger custom_exercises.custom_exercises_guard O 1794ab7f49e4a24c9a4325fc32bcbd35',
    'trigger entries.entries_guard O f1073a3a733224c943a6693a2b29c66a',
    'trigger food_entries.food_entries_guard O 12c938413a01acd96b0900fd4b76b517',
    'trigger food_targets.food_targets_guard O cacc0a2c0c5b6afd33c4812601175bfb',
    'trigger goals.goals_guard O 0520614b7762ac0683f44bdd3dc7a641',
    'trigger home_layout.home_layout_guard O 107b0ec062f2c101fe1a83867d66dd26',
    'trigger machine_notes.machine_notes_guard O 01d467a0997dd9f9c631e150be7a61a4',
    'trigger meals.meals_guard O 8e74d57f7048ab2296f16bfd6b424af2',
    'trigger measurements.measurements_guard O 83edde0ef4246f082f8cc9b7dcaa28a8',
    'trigger pauses.pauses_guard O dbe06afe3329680ef61178ef66c62c39',
    'trigger photos.photos_guard O 2914390d56715495d190fef78614903f',
    'trigger plan_days.plan_days_guard O 0829acbd866ca6549aaaabb93f6e1a48',
    'trigger plans.plans_guard O c2e72dcae7074c83e26833178c641982',
    'trigger profile.profile_guard O 34370a47fb1cb27654eaeb960919ce7a',
    'trigger purges.native_pwa_purge O 8a73c844504fd9858319084abec48579',
    'trigger purges.purges_guard O e6ebbeee1cbb0448f162f08a5d75a696',
    'trigger routine_exercises.routine_exercises_guard O a6a443d7b98c6afe7a81d69cfd9eefce',
    'trigger routines.routines_guard O f52c5977ff2ceb612bb78bbb2a3485e6',
    'trigger saved_foods.saved_foods_guard O a58f2384c6007f779a9b182a3908cb0f',
    'trigger sessions.sessions_guard O c602f304de97a502f0e64563fa422e16',
    'trigger sets.sets_guard O f9b9dcc22721bc9c992fcc82489b7050',
    'trigger settings.settings_guard O 6db8966e9dd43529ed0bfa34038635e8',
    'trigger weigh_ins.weigh_ins_guard O b229e0bd5ae61777447e2e2fc59c2ebc'
  ]::text[];
  live text[];
  report text;
BEGIN
  SELECT pg_catalog.array_agg(line ORDER BY line) INTO live FROM (
  WITH t(name) AS (SELECT pg_catalog.unnest(ARRAY['profile','weigh_ins','measurements','routines','routine_exercises','sessions','entries','sets','cardio_sessions','food_entries','saved_foods','food_targets','meals','goals','plan_days','machine_notes','home_layout','settings','photos','custom_exercises','plans','pauses','purges']::text[])),
  rel AS (SELECT t.name, c.oid FROM t JOIN pg_catalog.pg_class c ON c.relname = t.name
            JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public' AND c.relkind = 'r'),
  f AS (SELECT p.* FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname = 'public' AND p.proname IN ('row_sync_guard','sync_push','sync_purge_range','native_pwa_invalidate_on_purge'))
  SELECT 'table ' || name FROM rel
  UNION ALL SELECT 'column ' || c.table_name || '.' || c.column_name || ' ' || c.data_type
       || CASE WHEN c.is_nullable = 'NO' THEN ' not null' ELSE '' END
       || COALESCE(' default ' || c.column_default, '')
    FROM information_schema.columns c JOIN rel ON rel.name = c.table_name WHERE c.table_schema = 'public'
  UNION ALL SELECT 'rls ' || rel.name || CASE WHEN c.relrowsecurity THEN ' on' ELSE ' off' END
       || CASE WHEN c.relforcerowsecurity THEN ' forced' ELSE '' END
    FROM rel JOIN pg_catalog.pg_class c ON c.oid = rel.oid
  UNION ALL SELECT 'policy ' || p.tablename || '.' || p.policyname || ' ' || p.cmd || ' ' || p.permissive
       || ' ' || pg_catalog.array_to_string(p.roles, ',') || ' using ' || COALESCE(p.qual, '-')
       || ' check ' || COALESCE(p.with_check, '-')
    FROM pg_catalog.pg_policies p JOIN rel ON rel.name = p.tablename WHERE p.schemaname = 'public'
  UNION ALL SELECT 'trigger ' || rel.name || '.' || g.tgname || ' ' || g.tgenabled::text || ' '
       || pg_catalog.md5(pg_catalog.pg_get_triggerdef(g.oid))
    FROM rel JOIN pg_catalog.pg_trigger g ON g.tgrelid = rel.oid AND NOT g.tgisinternal
  UNION ALL SELECT 'index ' || i.tablename || '.' || i.indexname || ' ' || pg_catalog.md5(i.indexdef)
    FROM pg_catalog.pg_indexes i JOIN rel ON rel.name = i.tablename WHERE i.schemaname = 'public'
  UNION ALL SELECT 'grant ' || r.role || ' ' || rel.name || ' '
       || COALESCE(NULLIF(pg_catalog.concat_ws(',',
            CASE WHEN pg_catalog.has_table_privilege(r.role, rel.oid, 'SELECT') THEN 'select' END,
            CASE WHEN pg_catalog.has_table_privilege(r.role, rel.oid, 'INSERT') THEN 'insert' END,
            CASE WHEN pg_catalog.has_table_privilege(r.role, rel.oid, 'UPDATE') THEN 'update' END,
            CASE WHEN pg_catalog.has_table_privilege(r.role, rel.oid, 'DELETE') THEN 'delete' END), ''), 'none')
    FROM rel CROSS JOIN (VALUES ('anon'), ('authenticated')) r(role)
  UNION ALL SELECT 'sequence ' || c.relname FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'public' AND c.relkind = 'S' AND c.relname = 'row_sync_seq'
  UNION ALL SELECT 'function ' || f.proname || '(' || pg_catalog.pg_get_function_identity_arguments(f.oid) || ')'
       || ' returns ' || pg_catalog.pg_get_function_result(f.oid)
       || CASE WHEN f.prosecdef THEN ' definer' ELSE ' invoker' END
       || ' ' || COALESCE(pg_catalog.array_to_string(f.proconfig, ','), '-')
       || ' body ' || pg_catalog.md5(f.prosrc)
    FROM f
  UNION ALL SELECT 'execute ' || r.role || ' ' || f.proname || ' '
       || CASE WHEN pg_catalog.has_function_privilege(r.role, f.oid, 'EXECUTE') THEN 'yes' ELSE 'no' END
    FROM f CROSS JOIN (VALUES ('anon'), ('authenticated')) r(role)
  ) AS shape(line);
  SELECT pg_catalog.string_agg(kind || ': ' || line, E'\n' ORDER BY line, kind) INTO report FROM (
    SELECT 'missing' AS kind, e AS line FROM pg_catalog.unnest(expected) e
     WHERE e <> ALL (COALESCE(live, ARRAY[]::text[]))
    UNION ALL
    SELECT 'unexpected', l FROM pg_catalog.unnest(live) l WHERE l <> ALL (expected)
  ) AS d;
  IF report IS NOT NULL THEN
    RAISE EXCEPTION E'Row-sync on this database differs from the plan:\n%', report;
  END IF;
  RAISE NOTICE 'Row-sync matches the plan: % facts compared.', pg_catalog.array_length(expected, 1);
END $$;
SELECT 'Row-sync matches the plan' AS result;
ROLLBACK;
